1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface Damage {
9	  itemType: string;
10	  amount: number;
11	}
12	
13	export interface Incident {
14	  cause: string;
15	  damages: Damage[];
16	}
17	
18	export type Step =
19	  | { op: "quote"; items: Item[] }
20	  | { op: "claim"; policy: number; incident: Incident };
21	
22	export interface Scenario {
23	  customer: { yearsWithMHPCO: number };
24	  steps: Step[];
25	}
26	
27	export type QuoteResult = { premium: number };
28	export type ClaimResult = { payout: number; remainingCap: number };
29	export type Result = QuoteResult | ClaimResult;
30	
31	export interface ScenarioOutcome {
32	  results: Result[];
33	}
